-----------------------------------------------------------------------
-- ARTICLE 1: Configuring LDAP Authentication in Niagara 4
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'how-to-niagara'),
  'Configuring LDAP Authentication in Niagara 4',
  'niagara-ldap-authentication-active-directory',
  'Step-by-step guide to integrating Niagara 4 stations with Active Directory for centralized user management via LDAP, including TLS requirements and troubleshooting.',
  E'# Configuring LDAP Authentication in Niagara 4\n\nCentralized authentication through LDAP lets you manage Niagara user accounts from Active Directory instead of maintaining separate credentials on every station. This eliminates password sprawl and simplifies user onboarding and offboarding.\n\n## Prerequisites\n\n| Requirement | Details |\n|---|---|\n| Niagara version | 4.6 or later |\n| License | LDAP module included in station license |\n| Network | Station must reach domain controller on port 389 (LDAP) or 636 (LDAPS) |\n| AD service account | Read-only account for directory queries |\n| TLS certificate | Required for LDAPS (strongly recommended) |\n\n## Architecture Overview\n\n```\nUser Browser → Niagara Station → LDAP Query → Active Directory\n                    ↓                              ↓\n              Local Auth (fallback)          AD Groups → Niagara Roles\n```\n\n## Step 1: Install the LDAP Module\n\n1. Open Niagara Workbench\n2. Connect to the target station\n3. Open the **Software Manager**\n4. Install the `ldap` module if not already present\n5. Restart the station\n\n## Step 2: Add the LDAP User Service\n\n1. Navigate to **Config > Services > UserService**\n2. Right-click and select **Add > LdapUserService**\n3. The LDAP User Service will appear alongside the existing local UserService\n\n## Step 3: Configure the LDAP Connection\n\nOpen the LdapUserService properties:\n\n```\nLDAP Configuration:\n  Server URL: ldaps://dc01.company.com:636\n  Base DN: DC=company,DC=com\n  Bind DN: CN=NiagaraSvc,OU=Service Accounts,DC=company,DC=com\n  Bind Password: ********\n  User Search Filter: (&(objectClass=user)(sAMAccountName={0}))\n  Search Subtree: true\n  Connection Timeout: 5000 ms\n  Read Timeout: 10000 ms\n```\n\n### Connection URL Options\n\n| Protocol | Port | Security | Recommendation |\n|---|---|---|---|\n| `ldap://` | 389 | None | Development only |\n| `ldaps://` | 636 | SSL/TLS | Production use |\n| `ldap://` + StartTLS | 389 | TLS upgrade | Alternative to LDAPS |\n\n## Step 4: Configure TLS Certificate Trust\n\nFor LDAPS connections, the station must trust the AD certificate:\n\n1. Export the AD CA certificate (Base64 .cer format)\n2. Import into the Niagara station''s trust store:\n\n```\nWorkbench > Platform > Trust Store Manager\n  → Import Certificate\n  → Select the AD CA certificate\n  → Restart station\n```\n\n## Step 5: Map AD Groups to Niagara Roles\n\nMap Active Directory groups to Niagara roles:\n\n```\nGroup Mappings:\n  CN=BAS-Admins,OU=Groups,DC=company,DC=com → admin\n  CN=BAS-Operators,OU=Groups,DC=company,DC=com → operator\n  CN=BAS-Viewers,OU=Groups,DC=company,DC=com → viewer\n```\n\n| AD Group | Niagara Role | Access Level |\n|---|---|---|\n| BAS-Admins | admin | Full configuration access |\n| BAS-Operators | operator | Read + command, no config |\n| BAS-Viewers | viewer | Read-only monitoring |\n\n## Step 6: Set Authentication Order\n\nConfigure the station to try LDAP first, then fall back to local:\n\n```\nAuthentication Order:\n  1. LdapUserService (primary)\n  2. UserService (fallback)\n```\n\nKeep at least one local admin account as a fallback in case the domain controller is unreachable.\n\n## Step 7: Enforce Secure Transport\n\nLDAP credentials travel over the network, so enforce HTTPS:\n\n1. Navigate to **Config > Services > WebService**\n2. Set **Https Only** to `true`\n3. Configure FOXS for Workbench connections\n\n## Troubleshooting\n\n### Bind Failures\n\n| Symptom | Cause | Fix |\n|---|---|---|\n| "LDAP error code 49" | Invalid credentials | Verify bind DN and password |\n| "Connection refused" | Wrong port or firewall | Check port 636 is open |\n| "Certificate not trusted" | Missing CA cert | Import AD CA into trust store |\n| "Timeout" | DNS or routing issue | Verify station can ping DC |\n\n### Password Expiration Lockouts\n\nIf the AD service account password expires, all LDAP authentication fails:\n\n- Set the service account to **Password Never Expires** in AD\n- Or implement a password rotation procedure with scheduled maintenance\n- Local fallback admin account prevents complete lockout\n\n### Users Cannot Log In After AD Migration\n\n- Verify the User Search Filter matches your AD schema\n- Check that `sAMAccountName` is correct (some environments use `userPrincipalName`)\n- Enable LDAP debug logging: **LdapUserService > Log Level = Fine**\n\n## Security Considerations\n\n- Always use LDAPS (port 636) in production\n- Use a dedicated read-only service account with minimal permissions\n- Restrict the Base DN to the specific OU containing BAS users\n- Audit LDAP login events through Niagara''s audit log\n- Rotate the service account password on a regular schedule\n\n## References\n\n- Tridium Niagara 4 LDAP Integration Guide\n- Microsoft Active Directory LDAP reference\n- ASHRAE Guideline 13: Specifying DDC Systems\n\nProper LDAP integration means one less password for technicians to remember and one less account for IT to manage when someone leaves the organization.',
  true
);

INSERT INTO wiki_article_tags (article_id, tag_id)
SELECT
  (SELECT id FROM wiki_articles WHERE slug = 'niagara-ldap-authentication-active-directory'),
  id
FROM wiki_tags WHERE slug IN ('niagara', 'authentication', 'security', 'certificate');

-----------------------------------------------------------------------
-- ARTICLE 2: Metasys Database Backup, Restore, and Maintenance
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'how-to-metasys'),
  'Metasys Database Backup, Restore, and Maintenance',
  'metasys-database-backup-restore-maintenance',
  'Comprehensive guide to managing the Metasys SQL Server Express database, including backup scheduling, restore procedures, purging, and handling the 10 GB size limit.',
  E'# Metasys Database Backup, Restore, and Maintenance\n\nMetasys stores alarms, trends, audit trails, and configuration data in SQL Server Express databases. Proper backup and maintenance prevents data loss and avoids the 10 GB Express edition size limit that can bring a system to a halt.\n\n## Database Architecture\n\nMetasys uses multiple databases:\n\n| Database | Contents | Growth Rate |\n|---|---|---|\n| ADSAlarmDatabase | Alarm and event history | High |\n| ADSAuditDatabase | User action audit trails | Medium |\n| ADSTrendDatabase | Trend sample data | Very High |\n| ADSConfigDatabase | System configuration | Low |\n\n## SQL Server Express Limitations\n\n| Constraint | Limit | Impact |\n|---|---|---|\n| Database size | 10 GB per database | System stops logging when reached |\n| RAM usage | 1 GB | Slower queries on large datasets |\n| CPU cores | 1 socket / 4 cores | Limited concurrent performance |\n| SQL Agent | Not available | Cannot use built-in job scheduler |\n\n## Backup Procedures\n\n### Using Metasys Database Manager\n\nThe built-in Database Manager provides the simplest backup approach:\n\n1. Open **Metasys Database Manager** from the Start menu\n2. Select the database to back up\n3. Choose a backup destination folder\n4. Click **Backup**\n\n```\nDefault Backup Location:\n  C:\\ProgramData\\Johnson Controls\\MetasysIII\\Backup\\\n\nBackup File Format:\n  ADSAlarmDatabase_YYYY-MM-DD_HHMMSS.bak\n```\n\n### Automating Backups Without SQL Agent\n\nSQL Server Express lacks SQL Agent, but you can use Windows Task Scheduler:\n\n```\nBackup Script (backup_metasys.bat):\n  sqlcmd -S .\\INTADSERVER -Q \"BACKUP DATABASE [ADSAlarmDatabase] TO DISK=''C:\\Backups\\Alarm_%date:~-4%-%date:~4,2%-%date:~7,2%.bak'' WITH COMPRESSION\"\n  sqlcmd -S .\\INTADSERVER -Q \"BACKUP DATABASE [ADSTrendDatabase] TO DISK=''C:\\Backups\\Trend_%date:~-4%-%date:~4,2%-%date:~7,2%.bak'' WITH COMPRESSION\"\n```\n\nSchedule this via Task Scheduler to run nightly.\n\n### Backup Best Practices\n\n- Back up all databases before any Metasys upgrade\n- Store backups on a separate drive or network share\n- Keep at least 7 days of backup history\n- Test restore procedures quarterly\n- Document the SQL Server instance name (usually `INTADSERVER`)\n\n## Restore Procedures\n\n### Full Database Restore\n\n1. Stop all Metasys services\n2. Open Metasys Database Manager\n3. Select **Restore** and browse to the `.bak` file\n4. Confirm the restore operation\n5. Restart Metasys services\n\n### Restoring Across SQL Server Versions\n\nWhen upgrading Metasys to a new version with a newer SQL Server:\n\n- Backups from older SQL Server versions can restore to newer versions\n- Backups from newer versions **cannot** restore to older versions\n- Always upgrade SQL Server before attempting the restore\n\n## Database Purging\n\n### Managing the 10 GB Limit\n\nMonitor database sizes regularly:\n\n```\nCheck Database Size:\n  sqlcmd -S .\\INTADSERVER -Q \"SELECT DB_NAME(database_id) AS Name, size*8/1024 AS SizeMB FROM sys.master_files WHERE type = 0\"\n```\n\n### Purge Strategies\n\n| Strategy | Method | Impact |\n|---|---|---|\n| Automatic purge | Configure in Database Manager | Set retention period (e.g., 90 days) |\n| Manual purge | Delete records older than date | Immediate space recovery |\n| Archive and purge | Backup then purge | Preserves historical data |\n\n### Configuring Automatic Purging\n\n```\nDatabase Manager > Maintenance:\n  Alarm Retention: 180 days\n  Trend Retention: 365 days\n  Audit Retention: 365 days\n  Purge Schedule: Weekly (Sunday 2:00 AM)\n```\n\n## Troubleshooting\n\n### \"Database Full\" Errors\n\n```\nSymptom: Alarms stop logging, trends show gaps\nCause: Database reached 10 GB Express limit\n\nImmediate Fix:\n  1. Run emergency purge of oldest data\n  2. Shrink database files\n  3. Verify logging resumes\n\nLong-term Fix:\n  - Implement automatic purging\n  - Reduce trend sample rates where possible\n  - Consider SQL Server Standard for large sites\n```\n\n### \"Database in Use\" During Restore\n\n```\nFix:\n  1. Stop all Metasys services (ADS, OAS, etc.)\n  2. Close all SQL Management Studio connections\n  3. Set database to single-user mode if needed\n  4. Retry the restore\n  5. Set back to multi-user mode\n  6. Restart Metasys services\n```\n\n### Corrupted Database\n\n```\nDiagnosis:\n  DBCC CHECKDB (''ADSAlarmDatabase'') WITH NO_INFOMSGS\n\nRepair (last resort):\n  ALTER DATABASE [ADSAlarmDatabase] SET SINGLE_USER WITH ROLLBACK IMMEDIATE\n  DBCC CHECKDB (''ADSAlarmDatabase'', REPAIR_ALLOW_DATA_LOSS)\n  ALTER DATABASE [ADSAlarmDatabase] SET MULTI_USER\n```\n\n## Maintenance Schedule\n\n| Task | Frequency | Method |\n|---|---|---|\n| Full backup | Daily | Automated script |\n| Size monitoring | Weekly | Database Manager or script |\n| Purge old records | Monthly | Automatic purge setting |\n| Index maintenance | Quarterly | Rebuild indexes |\n| Integrity check | Quarterly | DBCC CHECKDB |\n| Test restore | Quarterly | Restore to test environment |\n\n## References\n\n- Johnson Controls Metasys Database Manager Help\n- Microsoft SQL Server Express documentation\n- Johnson Controls Metasys Installation and Upgrade Guide\n\nA healthy database is the foundation of a reliable Metasys system. Schedule maintenance before the 10 GB limit forces an emergency intervention.',
  true
);

INSERT INTO wiki_article_tags (article_id, tag_id)
SELECT
  (SELECT id FROM wiki_articles WHERE slug = 'metasys-database-backup-restore-maintenance'),
  id
FROM wiki_tags WHERE slug IN ('metasys', 'database', 'best-practices', 'troubleshooting');

-----------------------------------------------------------------------
-- ARTICLE 3: Building Reusable PX Graphics with Parameters in Niagara
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'how-to-niagara'),
  'Building Reusable PX Graphics with Parameters in Niagara',
  'niagara-reusable-px-graphics-parameters',
  'Practical techniques for building parameterized, reusable PX pages in Niagara to eliminate copy-paste graphics sprawl and improve load performance.',
  E'# Building Reusable PX Graphics with Parameters in Niagara\n\nCopy-pasting PX pages for each piece of equipment creates a maintenance nightmare. When you need to update a graphic element, you must change it in dozens of places. Parameterized PX pages solve this by using a single template that dynamically binds to any equipment instance.\n\n## The Problem with Copy-Paste Graphics\n\n```\nTraditional approach (100 VAVs = 100 pages):\n  /Graphics/AHU-1/VAV-101.px\n  /Graphics/AHU-1/VAV-102.px\n  /Graphics/AHU-1/VAV-103.px\n  ... (97 more identical pages with hardcoded ORDs)\n\nParameterized approach (100 VAVs = 1 template):\n  /Graphics/Templates/VAV_Template.px\n  (dynamically resolves to any VAV via URL parameters)\n```\n\n| Approach | Pages to maintain | Update effort | Load time |\n|---|---|---|---|\n| Copy-paste | 100 | Change all 100 | Slower (larger station) |\n| Parameterized | 1 | Change once | Faster (smaller footprint) |\n\n## URL Parameter Binding\n\n### Basic Parameter Syntax\n\nPass equipment references via URL query parameters:\n\n```\nhttps://station/ord/Graphics/Templates/VAV.px?equip=slot:/AHU1/VAV101\n```\n\nIn the PX page, bind widgets using the parameter:\n\n```\nWidget ORD binding:\n  #{equip}/ZoneTemp\n  #{equip}/DamperPosition\n  #{equip}/HeatingValve\n  #{equip}/OccupiedSetpoint\n```\n\n### Navigation Links\n\nCreate equipment lists that link to the template:\n\n```\nFloor Plan Links:\n  VAV-101 → /ord/Graphics/Templates/VAV.px?equip=slot:/AHU1/VAV101\n  VAV-102 → /ord/Graphics/Templates/VAV.px?equip=slot:/AHU1/VAV102\n  VAV-103 → /ord/Graphics/Templates/VAV.px?equip=slot:/AHU1/VAV103\n```\n\n## Building a Reusable Template\n\n### Step 1: Design the Layout\n\nCreate the PX page with placeholder bindings:\n\n1. Open PX Editor in Workbench\n2. Design the graphic for one equipment type (e.g., VAV)\n3. Use relative ORD bindings with parameter references\n4. Add a title widget that displays the equipment name dynamically\n\n### Step 2: Use Relative ORDs\n\nAvoid absolute ORDs that lock you to a specific instance:\n\n```\nBad (absolute):\n  station:|slot:/AHU1/VAV101/ZoneTemp\n\nGood (parameterized):\n  #{equip}/ZoneTemp\n\nGood (relative to page context):\n  ./ZoneTemp\n```\n\n### Step 3: Add Dynamic Labels\n\nDisplay the equipment name in the page header:\n\n```\nTitle Widget:\n  Text: #{equip}\n  Or use: #{equip}/displayName\n```\n\n### Step 4: Handle Optional Points\n\nNot all equipment instances have the same points. Use conditional visibility:\n\n```\nWidget Visibility Binding:\n  Visible When: #{equip}/ReheatValve exists\n  Hidden When: point not found\n```\n\n## PX Includes for Reusable Components\n\nBreak common elements into reusable includes:\n\n```\nProject Structure:\n  /Graphics/Includes/\n    Header.px          (site name, navigation, clock)\n    StatusBar.px       (alarm counts, user info)\n    TempGauge.px       (reusable temperature display)\n    DamperWidget.px    (reusable damper graphic)\n    ValveWidget.px     (reusable valve graphic)\n\n  /Graphics/Templates/\n    AHU.px             (uses includes + parameters)\n    VAV.px             (uses includes + parameters)\n    Boiler.px          (uses includes + parameters)\n```\n\n### Creating a PX Include\n\n1. Design the component as a standalone PX file\n2. Define input parameters for the include\n3. Reference the include from parent pages:\n\n```\nParent page reference:\n  <include href=\"/Graphics/Includes/TempGauge.px\"\n           point=\"#{equip}/ZoneTemp\"\n           label=\"Zone Temperature\" />\n```\n\n## Performance Optimization\n\n### Why PX Pages Load Slowly\n\n| Cause | Impact | Fix |\n|---|---|---|\n| Too many widgets per page | Long render time | Split into sub-pages |\n| Absolute ORD resolution | Unnecessary network calls | Use relative ORDs |\n| Large background images | Slow download | Compress to <100KB |\n| Excessive animations | CPU load on client | Limit to status indicators |\n| Hundreds of copy-paste pages | Large station database | Switch to templates |\n\n### Optimization Checklist\n\n- Keep pages under 100 widgets where possible\n- Compress background images (PNG to optimized PNG or SVG)\n- Use CSS styling instead of image-based styling\n- Avoid polling intervals under 5 seconds unless necessary\n- Test page load times in a browser (not just Workbench preview)\n- Profile with browser DevTools to find slow bindings\n\n## Text and Layout Guidelines\n\n### Typography for Readability\n\n| Element | Size | Weight | Color |\n|---|---|---|---|\n| Page title | 18-24px | Bold | Primary |\n| Section header | 14-16px | Semi-bold | Primary |\n| Value labels | 11-12px | Normal | Secondary |\n| Point values | 14-16px | Bold | Status-dependent |\n| Units | 10-11px | Normal | Muted |\n\n### Color Coding Standards\n\n```\nStatus Colors:\n  Normal:    Green (#4CAF50)\n  Warning:   Amber (#FF9800)\n  Alarm:     Red (#F44336)\n  Offline:   Gray (#9E9E9E)\n  Override:  Blue (#2196F3)\n```\n\n## Testing PX Pages\n\n1. **Workbench Preview**: Quick check of layout and bindings\n2. **Browser Test**: Test actual load performance in Chrome/Edge\n3. **Mobile Test**: Verify responsive behavior on tablets\n4. **Multiple Instances**: Test the template with different equipment to verify all bindings resolve\n5. **Missing Points**: Test with equipment that has fewer points to verify graceful handling\n\n## References\n\n- Tridium Niagara PX Editor Documentation\n- Niagara Community PX Best Practices Guide\n- Tridium Developer Documentation: ORD Resolution\n\nA well-designed template library pays for itself the first time you need to update a graphic element across 100 pieces of equipment and it takes 5 minutes instead of 5 hours.',
  true
);

INSERT INTO wiki_article_tags (article_id, tag_id)
SELECT
  (SELECT id FROM wiki_articles WHERE slug = 'niagara-reusable-px-graphics-parameters'),
  id
FROM wiki_tags WHERE slug IN ('niagara', 'px', 'graphics', 'best-practices', 'performance');

-----------------------------------------------------------------------
-- ARTICLE 4: BACnet/SC (Secure Connect) Implementation Guide
-----------------------------------------------------------------------
INSERT INTO wiki_articles (category_id, title, slug, summary, content, is_published)
VALUES (
  (SELECT id FROM wiki_categories WHERE slug = 'how-to-general'),
  'BACnet/SC (Secure Connect) Implementation Guide',
  'bacnet-sc-secure-connect-implementation',
  'Practical walkthrough of deploying BACnet Secure Connect including hub/node configuration, certificate management, and migration from traditional BACnet/IP.',
  E'# BACnet/SC (Secure Connect) Implementation Guide\n\nBACnet Secure Connect (BACnet/SC) adds TLS encryption and certificate-based authentication to BACnet communications. It runs over standard IT infrastructure (WebSockets over TCP) instead of UDP broadcasts, making it firewall-friendly and suitable for modern network architectures.\n\n## Why BACnet/SC?\n\nTraditional BACnet/IP has no built-in security:\n\n| Feature | BACnet/IP | BACnet/SC |\n|---|---|---|\n| Encryption | None | TLS 1.3 |\n| Authentication | None | X.509 certificates |\n| Transport | UDP broadcast | WebSocket over TCP |\n| Firewall-friendly | No (requires BBMD) | Yes (standard HTTPS ports) |\n| IT approval | Difficult | Easier |\n| Specification | ASHRAE 135 Annex J | ASHRAE 135 Addendum BJ |\n\n## Architecture Overview\n\n```\n                    ┌─────────────┐\n                    │ Primary Hub │\n                    │  (TLS 1.3)  │\n                    └──────┬──────┘\n                           │\n              ┌────────────┼────────────┐\n              │            │            │\n        ┌─────┴─────┐ ┌───┴───┐ ┌─────┴─────┐\n        │  Node A   │ │Node B │ │  Node C   │\n        │ (Controller)│ │(JACE) │ │(Controller)│\n        └───────────┘ └───────┘ └───────────┘\n```\n\n### Hub and Node Roles\n\n| Role | Function | Typical Device |\n|---|---|---|\n| Hub | Central message broker, accepts node connections | Supervisor, server |\n| Failover Hub | Backup hub for redundancy | Second supervisor |\n| Node | Connects to hub, sends/receives BACnet messages | Controller, JACE |\n| Direct Connect | Node-to-node without hub (limited use) | Point-to-point |\n\n## Certificate Requirements\n\nBACnet/SC uses X.509 certificates for mutual TLS authentication:\n\n```\nCertificate Chain:\n  Root CA Certificate\n    └── Operational Certificate (per device)\n         ├── Device UUID\n         ├── BACnet Device Instance\n         └── Key Usage: TLS Client + Server\n```\n\n### Certificate Specifications\n\n| Parameter | Requirement |\n|---|---|\n| Key type | ECC P-256 or P-384 |\n| Signature | ECDSA with SHA-256 or SHA-384 |\n| Validity | 1-5 years recommended |\n| Subject | Device UUID and BACnet device instance |\n| Key usage | Digital Signature, Key Agreement |\n| Extended key usage | TLS Web Server + Client Authentication |\n\n## Implementation Steps\n\n### Step 1: Plan Your PKI\n\nDecide on certificate authority strategy:\n\n- **Self-signed CA**: Suitable for single-site deployments\n- **Enterprise CA**: Use existing IT PKI infrastructure\n- **Third-party CA**: For multi-vendor, multi-site deployments\n\n### Step 2: Generate Certificates\n\nFor a self-signed deployment:\n\n```\nGenerate Root CA:\n  openssl ecparam -genkey -name prime256v1 -out ca-key.pem\n  openssl req -new -x509 -key ca-key.pem -out ca-cert.pem -days 3650\n\nGenerate Device Certificate:\n  openssl ecparam -genkey -name prime256v1 -out device-key.pem\n  openssl req -new -key device-key.pem -out device.csr\n  openssl x509 -req -in device.csr -CA ca-cert.pem -CAkey ca-key.pem -out device-cert.pem -days 365\n```\n\n### Step 3: Configure the Hub\n\nOn the designated hub device (e.g., Niagara Supervisor):\n\n```\nHub Configuration:\n  Enabled: true\n  Listen Port: 443 (or custom)\n  Hub Certificate: device-cert.pem\n  Hub Private Key: device-key.pem\n  Trusted CA Certificates: ca-cert.pem\n  Max Connections: 100\n  Connection Timeout: 30 seconds\n```\n\n### Step 4: Configure Nodes\n\nOn each node device:\n\n```\nNode Configuration:\n  Enabled: true\n  Primary Hub URI: wss://supervisor.building.local:443/bacnet-sc\n  Failover Hub URI: wss://supervisor2.building.local:443/bacnet-sc\n  Node Certificate: device-cert.pem\n  Node Private Key: device-key.pem\n  Trusted CA Certificates: ca-cert.pem\n  Reconnect Interval: 10 seconds\n```\n\n### Step 5: Configure Hub Redundancy\n\nFor failover protection:\n\n```\nPrimary Hub: supervisor1 (Active)\nFailover Hub: supervisor2 (Standby)\n\nFailover Behavior:\n  1. Node connects to Primary Hub\n  2. If Primary Hub unreachable → connect to Failover Hub\n  3. Periodically retry Primary Hub\n  4. When Primary Hub returns → reconnect to Primary\n```\n\n## Coexistence with Legacy BACnet/IP\n\nDuring migration, devices can support both protocols:\n\n```\nDual-Stack Configuration:\n  BACnet/IP: Enabled (for legacy devices)\n  BACnet/SC: Enabled (for SC-capable devices)\n\nTraffic Flow:\n  SC Node ←→ Hub ←→ SC Node     (encrypted)\n  SC Node ←→ Router ←→ IP Device (mixed)\n  IP Device ←→ IP Device         (unencrypted)\n```\n\n### Migration Strategy\n\n| Phase | Action | Timeline |\n|---|---|---|\n| 1 | Deploy hub infrastructure | Month 1 |\n| 2 | Enable SC on new controllers | Ongoing |\n| 3 | Upgrade existing controllers to SC | 6-12 months |\n| 4 | Disable legacy BACnet/IP | When all devices support SC |\n\n## Performance Considerations\n\n| Factor | Impact |\n|---|---|\n| TLS handshake | ~100ms initial connection |\n| Encryption overhead | <5% CPU increase |\n| WebSocket framing | Minimal bandwidth increase |\n| Hub bandwidth | Scales with connected nodes |\n\n## Troubleshooting\n\n| Issue | Cause | Resolution |\n|---|---|---|\n| Node cannot connect to hub | Certificate not trusted | Import CA certificate on both sides |\n| TLS handshake failure | Expired certificate | Renew device certificate |\n| Intermittent disconnects | Network instability | Check TCP keepalive settings |\n| Slow discovery | Too many nodes on one hub | Consider multiple hubs |\n| Mixed traffic issues | Routing misconfiguration | Verify dual-stack settings |\n\n## References\n\n- ASHRAE 135-2020 Addendum BJ: BACnet/SC\n- BACnet International BACnet/SC Implementation Guide\n- Tridium BACnet/SC Configuration Guide\n\nBACnet/SC is the future of secure building automation communications. Starting with new installations and gradually migrating existing infrastructure provides a practical path to encrypted, authenticated BAS networks.',
  true
);

INSERT INTO wiki_article_tags (article_id, tag_id)
SELECT
  (SELECT id FROM wiki_articles WHERE slug = 'bacnet-sc-secure-connect-implementation'),
  id
FROM wiki_tags WHERE slug IN ('bacnet', 'security', 'niagara', 'certificate', 'networking');

